INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''scouring'' in textile wet processing?', '["A cleaning process that removes natural impurities (waxes, oils, dirt) and sizing agents from fiber/fabric before dyeing","The process of adding color to fabric","The final pressing/ironing of finished fabric","The process of weaving warp and weft together"]'::jsonb, 'A cleaning process that removes natural impurities (waxes, oils, dirt) and sizing agents from fiber/fabric before dyeing', 'Scouring uses alkali/detergent treatment to remove natural fiber impurities (cotton wax, seed husk, oils) and any sizing chemicals applied before weaving, ensuring the fabric is clean and absorbent for uniform dyeing.', 1, '{"scouring"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''bleaching'' in textile processing?', '["A chemical treatment that removes natural coloring matter from fiber, producing a whiter base for dyeing or finishing","The process of adding permanent color to fabric","The mechanical process of raising fabric nap","The process of shrinking fabric intentionally"]'::jsonb, 'A chemical treatment that removes natural coloring matter from fiber, producing a whiter base for dyeing or finishing', 'Bleaching (using agents like hydrogen peroxide or sodium hypochlorite) destroys natural pigments and residual impurities in fiber, producing a clean white base ideal for pale/bright dyeing or finishing as white goods.', 1, '{"bleaching"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'Why is scouring typically performed BEFORE dyeing, rather than after?', '["Impurities like wax and oil on unscoured fiber would block dye absorption, causing uneven/patchy dyeing","Scouring has no relationship to dye uptake at all","Dyeing always removes impurities on its own without any scouring needed","Scouring is only ever done after dyeing, never before"]'::jsonb, 'Impurities like wax and oil on unscoured fiber would block dye absorption, causing uneven/patchy dyeing', 'Natural waxes, oils, and processing chemicals act as a barrier to dye penetration; scouring removes them first so the fiber surface is clean and uniformly absorbent, ensuring even, predictable dye uptake.', 1, '{"scouring","dyeing-sequence"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''mercerization'' in cotton fabric processing?', '["A caustic soda treatment under tension that increases luster, strength, and dye affinity of cotton","A process that removes all dye from fabric","A mechanical brushing process to raise fabric nap","A drying process using only heated air"]'::jsonb, 'A caustic soda treatment under tension that increases luster, strength, and dye affinity of cotton', 'Mercerization treats cotton with concentrated caustic soda (NaOH) under tension, causing the fiber to swell and become more rounded/lustrous; this permanently increases luster, tensile strength, and dye uptake/affinity.', 1, '{"mercerization"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why must mercerization be done under TENSION (rather than allowing the fabric to shrink freely)?', '["Tension prevents excessive fiber shrinkage/distortion while the caustic soda causes fiber swelling, preserving dimensional stability and maximizing luster development","Tension has no effect on the mercerization outcome at all","Tension is only needed to speed up the drying step afterward","Tension is applied only to prevent the fabric from tearing during dyeing, unrelated to mercerization chemistry"]'::jsonb, 'Tension prevents excessive fiber shrinkage/distortion while the caustic soda causes fiber swelling, preserving dimensional stability and maximizing luster development', 'Caustic soda causes cotton fibers to swell and their cross-section to become more circular; if allowed to shrink freely without tension, the fabric would distort excessively and the characteristic increase in luster (from more uniform light reflection) would be reduced.', 2, '{"mercerization","tension"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''dye exhaustion'' in a dyeing process?', '["The proportion (percentage) of dye that transfers from the dye bath (liquor) onto the fiber/fabric","The complete removal of dye from already-dyed fabric","The process of drying fabric after dyeing","The mechanical finishing step after dyeing"]'::jsonb, 'The proportion (percentage) of dye that transfers from the dye bath (liquor) onto the fiber/fabric', 'Exhaustion % measures how much dye actually leaves the dye liquor and is absorbed onto the substrate — high exhaustion means efficient dye use and less residual dye in the effluent (wastewater).', 1, '{"dye-exhaustion"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What does ''liquor ratio'' refer to in dyeing?', '["The ratio of the weight of dye liquor (water + chemicals) to the weight of the fabric/fiber being dyed","The ratio of dye powder to fixing agent used","The ratio of warp yarn to weft yarn in the fabric","The exact pH level of the dye bath"]'::jsonb, 'The ratio of the weight of dye liquor (water + chemicals) to the weight of the fabric/fiber being dyed', 'Liquor ratio (e.g., 1:10 means 1 kg fabric to 10 liters of liquor) is a key process parameter — it affects dye concentration, chemical costs, water/energy use, and how dye recipes must be adjusted between different machines.', 1, '{"liquor-ratio"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why does changing the liquor ratio (e.g., from 1:10 to 1:20) require recalculating the amount of dye/chemicals used, even for the same fabric weight?', '["Dye concentration in the bath changes with liquor volume, and this concentration (not just total dye weight) strongly affects exhaustion and shade depth","Liquor ratio has no effect on dye concentration or shade outcome","The fabric weight itself changes when liquor ratio changes","Dye chemicals dissolve differently depending only on water temperature, never volume"]'::jsonb, 'Dye concentration in the bath changes with liquor volume, and this concentration (not just total dye weight) strongly affects exhaustion and shade depth', 'Dye recipes are typically expressed as % on weight of fabric (%owf), but the actual bath CONCENTRATION (dye amount per liter of liquor) governs exhaustion kinetics — a higher liquor ratio dilutes the same %owf dye amount into more water, potentially reducing exhaustion and requiring recipe adjustment for consistent shade.', 2, '{"liquor-ratio","dye-concentration"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''reactive dye'' known for in cotton dyeing?', '["Forming a covalent chemical bond with the cellulose fiber, giving excellent wash fastness","Only physically coating the fiber surface with no chemical bonding","Being used exclusively on synthetic polyester fiber","Requiring no chemicals other than water and dye powder"]'::jsonb, 'Forming a covalent chemical bond with the cellulose fiber, giving excellent wash fastness', 'Reactive dyes contain reactive groups that form actual covalent bonds with cellulose hydroxyl groups, chemically attaching the dye to the fiber — this bonding gives reactive-dyed cotton excellent wash fastness compared to dyes that merely adsorb onto the fiber.', 1, '{"reactive-dye"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why is salt (sodium chloride or sodium sulfate) commonly added during reactive dyeing of cotton?', '["Salt helps drive dye exhaustion by reducing the electrostatic repulsion between the negatively charged dye and the negatively charged cellulose fiber surface","Salt directly bonds chemically with the fiber instead of the dye","Salt is added purely to change the fabric''s final color","Salt has no functional role and is only a traditional practice"]'::jsonb, 'Salt helps drive dye exhaustion by reducing the electrostatic repulsion between the negatively charged dye and the negatively charged cellulose fiber surface', 'Both reactive dye molecules and cellulose fiber carry a negative surface charge in water, which repels the dye away from the fiber; adding salt shields/reduces this repulsion (via ionic strength), promoting better dye exhaustion onto the fiber before the fixation (alkali) stage.', 2, '{"reactive-dyeing","salt"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is the role of alkali (e.g., soda ash) added LATER in the reactive dyeing process, after salt and initial exhaustion?', '["It activates the reactive dye''s reactive group and the cellulose''s hydroxyl groups, enabling the actual covalent fixation (bonding) reaction","It removes color from the fabric to correct mistakes","It has the same function as salt and is simply a backup ingredient","It only affects fabric softness, not dye fixation"]'::jsonb, 'It activates the reactive dye''s reactive group and the cellulose''s hydroxyl groups, enabling the actual covalent fixation (bonding) reaction', 'After salt promotes dye exhaustion (dye moving onto fiber), alkali raises the pH to activate the nucleophilic reaction between the reactive dye''s functional group and cellulose hydroxyls, forming the permanent covalent bond (fixation) that gives reactive dyeing its durability.', 2, '{"reactive-dyeing","alkali-fixation"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''disperse dye'' primarily used to dye?', '["Hydrophobic synthetic fibers like polyester","Natural cellulosic fibers like cotton exclusively","Only wool and other protein fibers","Only fibers that have already been mercerized"]'::jsonb, 'Hydrophobic synthetic fibers like polyester', 'Disperse dyes are very finely dispersed, low-water-solubility dye particles designed to dissolve into and diffuse within hydrophobic synthetic fibers (especially polyester), since polyester has no reactive/ionic sites for other dye classes to bond to.', 1, '{"disperse-dye"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why does dyeing polyester with disperse dye typically require high temperature (or a carrier chemical) compared to cotton reactive dyeing?', '["Polyester''s compact molecular structure has very low porosity at normal temperatures, and heat (or carriers) is needed to open up the fiber structure enough for dye molecules to diffuse in","Polyester actually dyes at lower temperature than cotton in every case","Disperse dyes chemically bond to polyester exactly like reactive dyes bond to cotton","Temperature has no effect on disperse dye penetration into polyester"]'::jsonb, 'Polyester''s compact molecular structure has very low porosity at normal temperatures, and heat (or carriers) is needed to open up the fiber structure enough for dye molecules to diffuse in', 'Polyester is a highly compact, hydrophobic polymer with little free volume for dye molecules to enter at room temperature; high-temperature (often pressurized, ~130°C) dyeing or carrier chemicals temporarily swell/soften the polymer structure enough for disperse dye diffusion into the fiber interior.', 2, '{"disperse-dye","polyester-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is a ''vat dye'' and what is unique about how it''s applied?', '["An insoluble dye that must first be chemically reduced to a soluble (''leuco'') form to penetrate fiber, then re-oxidized back to its insoluble colored form inside the fiber","A dye that is always soluble in water without any chemical treatment","A dye used exclusively for synthetic polyester fiber","A temporary dye that washes out completely after one wash"]'::jsonb, 'An insoluble dye that must first be chemically reduced to a soluble (''leuco'') form to penetrate fiber, then re-oxidized back to its insoluble colored form inside the fiber', 'Vat dyes (e.g., indigo) are naturally insoluble; a reducing agent converts them to a soluble leuco form that can penetrate the fiber, after which exposure to air/oxidizing agent converts the dye back to its original insoluble, colored, wash-fast form trapped inside the fiber.', 2, '{"vat-dye"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''colorfastness'' in textile testing?', '["A fabric''s resistance to color change or transfer (bleeding) when exposed to conditions like washing, light, or rubbing","The exact shade/hue of a dyed fabric","The chemical name of the dye used","The weight of dye applied per unit fabric weight"]'::jsonb, 'A fabric''s resistance to color change or transfer (bleeding) when exposed to conditions like washing, light, or rubbing', 'Colorfastness measures how well a dyed fabric retains its color (or avoids transferring color to other materials) under specific stress conditions — common tests include wash fastness, light fastness, and rubbing (crocking) fastness.', 1, '{"colorfastness"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What does ''crocking'' (or crock fastness) specifically test for in dyed fabric?', '["Color transfer from the fabric surface onto another material through rubbing/friction","Color fading from prolonged sunlight exposure","Color change from repeated washing in hot water","Color change from exposure to perspiration"]'::jsonb, 'Color transfer from the fabric surface onto another material through rubbing/friction', 'Crocking specifically tests dry and wet rub transfer — how much unfixed surface dye rubs off onto another (usually white) test fabric when the dyed fabric is rubbed against it, a common quality complaint especially with certain dark or poorly-fixed dyeings.', 1, '{"crocking","colorfastness"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''finishing'' in the broader textile production process (as distinct from dyeing/printing)?', '["A range of mechanical and/or chemical treatments applied to fabric after dyeing/printing to impart specific desired properties (softness, wrinkle resistance, water repellency, etc.)","The process of weaving warp and weft together","The initial cleaning process that removes fiber impurities","The process of spinning fiber into yarn"]'::jsonb, 'A range of mechanical and/or chemical treatments applied to fabric after dyeing/printing to impart specific desired properties (softness, wrinkle resistance, water repellency, etc.)', 'Finishing covers the final stage(s) of fabric treatment — mechanical (calendering, raising, sanforizing) and/or chemical (softening, durable-press resins, water-repellent coatings) — used to give the fabric its final hand, appearance, and functional performance.', 1, '{"finishing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''calendering'' as a mechanical finishing process?', '["Passing fabric through heated rollers under pressure to flatten, smooth, or add surface luster/effects","A chemical process that permanently dyes fabric","A process that raises fiber ends to create a fuzzy/napped surface","A washing process to remove sizing chemicals"]'::jsonb, 'Passing fabric through heated rollers under pressure to flatten, smooth, or add surface luster/effects', 'Calendering presses fabric between heated rollers (sometimes with engraved patterns) under controlled pressure, flattening the surface, increasing smoothness/luster, or creating specific surface textures like moiré or embossed effects.', 1, '{"calendering"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is the purpose of ''sanforization'' (compressive shrinkage finishing)?', '["To pre-shrink fabric mechanically before it''s cut/sewn, so the final garment doesn''t shrink significantly during later washing","To add a permanent bright color to the fabric","To remove all natural fiber impurities before dyeing","To insert additional weft yarns into the fabric"]'::jsonb, 'To pre-shrink fabric mechanically before it''s cut/sewn, so the final garment doesn''t shrink significantly during later washing', 'Sanforizing mechanically compresses fabric (compensating for the shrinkage that would otherwise occur during the customer''s first wash), so finished garments maintain stable dimensions through their useful life — commonly seen as a ''Sanforized'' label on cotton garments.', 1, '{"sanforization"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is a ''durable press'' (wrinkle-resistant) finish designed to achieve?', '["Chemically cross-linking cellulose fiber chains (often with resin treatment) so the fabric resists wrinkling and recovers its shape after creasing","Adding a temporary starch coating that washes out after one wash","Physically weaving the fabric more tightly to prevent any stretching","Removing all moisture-absorbing properties from the fiber permanently"]'::jsonb, 'Chemically cross-linking cellulose fiber chains (often with resin treatment) so the fabric resists wrinkling and recovers its shape after creasing', 'Durable press finishes use resin chemistry (often formaldehyde-based cross-linking agents, historically, now often lower-formaldehyde alternatives) to create cross-links between cellulose chains, giving the fiber ''memory'' to resist and recover from wrinkling.', 2, '{"durable-press-finish"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why might a durable-press (wrinkle-resistant) cotton finish sometimes reduce the fabric''s tensile strength and abrasion resistance compared to untreated cotton?', '["Cross-linking the cellulose chains restricts their natural flexibility/mobility, which can make the fiber more brittle and reduce its ability to absorb stress through fiber movement","Durable press treatment always adds strength with no tradeoff whatsoever","The finish removes all fiber from the fabric, replacing it with only resin","Tensile strength is entirely unrelated to any chemical treatment applied to fiber"]'::jsonb, 'Cross-linking the cellulose chains restricts their natural flexibility/mobility, which can make the fiber more brittle and reduce its ability to absorb stress through fiber movement', 'The same cross-links that lock cellulose chains in place to resist wrinkling also restrict the natural flexing/sliding of fiber molecules that normally helps absorb mechanical stress — this is a well-documented tradeoff, meaning durable-press cotton often has somewhat reduced strength/abrasion resistance versus untreated cotton.', 2, '{"durable-press","strength-tradeoff"}'::text[]);
